     1	#!/usr/bin/env node
     2	/*
     3	 * build/bundle.js — 把 js/lib/*.js + js/plugin.js + js/ui.js 打成单个 js/bundle.js
     4	 *
     5	 * 为什么需要：Eagle webview 加载 js/plugin.js 时 require('./lib/xxx') 抛错（issue #2），
     6	 *           推断 nodeIntegration 下相对路径解析不在 webview 文件原目录。
     7	 *           ship 单文件可绕开此限制。
     8	 *
     9	 * 怎么做：
    10	 *   - 维护 __cw_modules 表 + __cw_require(name) 同步函数
    11	 *   - 每个 lib/* 包 IIFE 注入到表里（带 module.exports / exports 影子变量）
    12	 *   - 把所有 require('./xxx') 重写为 __cw_require('lib/xxx')
    13	 *   - plugin.js / ui.js 作为入口 IIFE 放最后，执行其副作用（onPluginCreate / 暴露 window.*）
    14	 *
    15	 * 模块加载顺序按依赖关系硬编码，保证被依赖者先入表。
    16	 */
    17	
    18	const fs = require('fs')
    19	const path = require('path')
    20	
    21	const REPO = path.join(__dirname, '..')
    22	const LIB_DIR = path.join(REPO, 'js', 'lib')
    23	const OUT = path.join(REPO, 'js', 'bundle.js')
    24	
    25	// 依赖序：被依赖者在前
    26	const LIB_ORDER = [
    27	  'constants',
    28	  'utils',
    29	  'i18n',
    30	  'state',
    31	  'theme',
    32	  'notification',
    33	  'config',
    34	  'clipboard',
    35	  'folders',
    36	  'import',
    37	  'screenshot',
    38	  'instance', // v1.5.2：依赖 state，给 poll 用
    39	  'poll',
    40	]
    41	
    42	function read(p) {
    43	  return fs.readFileSync(p, 'utf8')
    44	}
    45	
    46	/**
    47	 * 把 require('./foo') 或 require('./lib/foo') 改写为 __cw_require('lib/foo')。
    48	 * 保留对 node 内置 / npm 模块的 require（os / fs / path / child_process / electron 等）。
    49	 */
    50	function rewrite(src) {
    51	  return src.replace(/require\(\s*(['"])\.\/([^'"]+?)\1\s*\)/g, (_full, _q, sub) => {
    52	    const key = `lib/${sub.replace(/^lib\//, '').replace(/\.js$/, '')}`
    53	    return `__cw_require('${key}')`
    54	  })
    55	}
    56	
    57	function wrapModule(name, src) {
    58	  return `
    59	// ===== ${name} =====
    60	__cw_modules['${name}'] = (function() {
    61	  const module = { exports: {} };
    62	  const exports = module.exports;
    63	${src}
    64	  return module.exports;
    65	})();
    66	`
    67	}
    68	
    69	function wrapEntry(label, src) {
    70	  // 入口跑副作用，不需要收 exports
    71	  return `
    72	// ===== ${label} (entry) =====
    73	;(function() {
    74	  const module = { exports: {} };
    75	  const exports = module.exports;
    76	${src}
    77	})();
    78	`
    79	}
    80	
    81	let out = `/* AUTO-GENERATED bundle — do not edit by hand.
    82	 * Source files: js/plugin.js, js/ui.js, js/lib/*.js
    83	 * Regenerate: npm run build
    84	 *
    85	 * Built at: ${new Date().toISOString()}
    86	 */
    87	;(function(){
    88	'use strict';
    89	
    90	const __cw_modules = {};
    91	function __cw_require(name) {
    92	  if (!Object.prototype.hasOwnProperty.call(__cw_modules, name)) {
    93	    throw new Error('[bundle] Module not found: ' + name);
    94	  }
    95	  return __cw_modules[name];
    96	}
    97	
    98	`
    99	
   100	for (const name of LIB_ORDER) {
   101	  const filePath = path.join(LIB_DIR, `${name}.js`)
   102	  const src = rewrite(read(filePath))
   103	  out += wrapModule(`lib/${name}`, src)
   104	}
   105	
   106	const pluginSrc = rewrite(read(path.join(REPO, 'js', 'plugin.js')))
   107	out += wrapEntry('plugin', pluginSrc)
   108	
   109	const uiSrc = rewrite(read(path.join(REPO, 'js', 'ui.js')))
   110	out += wrapEntry('ui', uiSrc)
   111	
   112	out += `\n})();\n`
   113	
   114	fs.writeFileSync(OUT, out)
   115	const sizeKB = (fs.statSync(OUT).size / 1024).toFixed(1)
   116	console.log(`✓ bundle: ${LIB_ORDER.length} libs + plugin + ui → ${path.relative(REPO, OUT)} (${sizeKB} KB)`)

