-  if (!state.instanceId) return null
-  try {
-    const raw = localStorage.getItem(HEARTBEAT_KEY)
-    if (!raw) return null
-    const hb = JSON.parse(raw)
-    if (!hb || typeof hb !== 'object' || !hb.instanceId) return null
-    if (hb.instanceId === state.instanceId) return null // 自己的
-    if (Date.now() - (hb.ts || 0) < HEARTBEAT_FRESH_MS) {
-      return {
-        otherInstanceId: hb.instanceId,
-        otherVersion: hb.version || 'unknown',
-      }
+    state.lastHeartbeatAt = currentTime
+
+    // setItem 是同步的；回读可防御同一事件循环中被其他实例抢写。
+    const confirmed = readLease()
+    if (confirmed && confirmed.instanceId !== state.instanceId) {
+      return { owned: false, conflict: toConflict(confirmed) }
     }
-    return null // 过期残留
+
+    return { owned: true, conflict: null }
   } catch {
-    return null
+    return { owned: true, conflict: null }
   }
 }

-module.exports = { initInstance, writeHeartbeat, checkConflict, PLUGIN_VERSION }
+function releaseLease() {
+  if (!state.instanceId) return
+  try {
+    const current = readLease()
+    if (current && current.instanceId === state.instanceId) {
