  if (!eagle.clipboard || typeof eagle.clipboard.has !== 'function') return false
  for (const fmt of candidates) {
    try {
      if (eagle.clipboard.has(fmt)) return true
    } catch {}
  }
  return false
}

function parsePathList(stdout) {
  if (typeof stdout !== 'string') return []
  return stdout
    .split(/\r?\n/)
    .map((s) => s.trim())
    .filter(Boolean)
    .slice(0, MULTI_FILE_MAX)
}

/** Linux text/uri-list → POSIX 路径列表 */
function parseUriList(stdout) {
  if (typeof stdout !== 'string') return []
  const out = []
  for (const line of stdout.split(/\r?\n/)) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    if (trimmed.startsWith('file://')) {
      try {
        const url = new URL(trimmed)
        out.push(decodeURIComponent(url.pathname))
      } catch {
        out.push(decodeURIComponent(trimmed.replace(/^file:\/\//, '')))
      }
    } else if (trimmed.startsWith('/')) {
      out.push(trimmed)
    }
  }
  return out.slice(0, MULTI_FILE_MAX)
}

/**
