        'try\n' +
        '  set theItems to the clipboard as «class furl»\n' +
        'on error\n' +
        '  return ""\n' +
        'end try\n' +
        'set thePaths to {}\n' +
        'try\n' +
        '  repeat with f in theItems\n' +
        '    set end of thePaths to POSIX path of f\n' +
        '  end repeat\n' +
        'on error\n' +
        '  try\n' +
        '    set end of thePaths to POSIX path of theItems\n' +
        '  end try\n' +
        'end try\n' +
        'set AppleScript\'s text item delimiters to linefeed\n' +
        'return thePaths as text'
      execFile(
        'osascript',
        ['-e', script],
        { timeout: SHELL_TIMEOUT_MS },
        (err, stdout) => {
          if (err) {
            eagle.log.warn(`[clipboard-watcher] osascript failed: ${err.message}`)
            resolve([])
            return
          }
          resolve(parsePathList(stdout))
        }
      )
    } else if (platform === 'win32') {
      const script =
        "$ErrorActionPreference='SilentlyContinue';" +
        " Get-Clipboard -Format FileDropList |" +
        ' ForEach-Object { $_.FullName }'
      execFile(
        'powershell',
        ['-NoProfile', '-NonInteractive', '-Command', script],
        { timeout: SHELL_TIMEOUT_MS },
        (err, stdout) => {
          if (err) {
            eagle.log.warn(`[clipboard-watcher] powershell failed: ${err.message}`)
            resolve([])
            return
          }
          resolve(parsePathList(stdout))
        }
      )
    } else if (platform === 'linux') {
      const isWayland = !!process.env.WAYLAND_DISPLAY
      const tryWlPaste = () =>
        new Promise((res) => {
          execFile(
            'wl-paste',
            ['--type', 'text/uri-list'],
            { timeout: SHELL_TIMEOUT_MS },
            (err, stdout) => {
              if (err) {
                res(null)
                return
              }
              res(parseUriList(stdout))
            }
          )
        })
      const tryXclip = () =>
        new Promise((res) => {
          execFile(
            'xclip',
            ['-selection', 'clipboard', '-t', 'text/uri-list', '-o'],
            { timeout: SHELL_TIMEOUT_MS },
            (err, stdout) => {
              if (err) {
                res(null)
                return
              }
              res(parseUriList(stdout))
            }
          )
        })
      const order = isWayland ? [tryWlPaste, tryXclip] : [tryXclip, tryWlPaste]
      ;(async () => {
        for (const fn of order) {
          const r = await fn()
          if (r && r.length) {
            resolve(r)
            return
          }
        }
        resolve([])
      })()
    } else {
      resolve([])
    }
  })
}

