async function enableWatcher() {
  if (!state.config.folderId) {
    setLastError(ERROR_CODES.NO_FOLDER_SELECTED)
    setRuntimeStatus('error', ERROR_CODES.NO_FOLDER_SELECTED)
    scheduleRender()
    return false
