function disableWatcher() {
  saveConfig({ enabled: false })
  stopPolling()
  stopLeaseMaintenance()
  releaseLease()
  setRuntimeStatus('idle')
  scheduleRender()
  eagle.log.info('[clipboard-watcher] watcher disabled')
