window.ClipboardWatcher = {
  // 用户操作
  enableWatcher,
  disableWatcher,
  selectFolder,
  updateIntervalMs,
  updateRouteFolder,
  triggerScreenshot,
  resetFolderIndex,
  openItem,
  // 配置
  saveConfig,
  buildDefaults,
  DEFAULT_NAME_TEMPLATE,
  previewNameTemplate,
  // 快照
  getSnapshot,
