    hint.textContent = t('fields.folder_hint_empty')
  } else if (!current) {
    hint.textContent = t('fields.folder_hint_pick')
  } else {
    hint.textContent = t('fields.folder_hint_current', null, snapshot.folderLabel || current)
  }
